def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n <= 4:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_d = opp.count('D')
    my_d = me.count('D')
    opp_rate = opp_d / n
    my_rate = my_d / n

    w5 = 5 if n >= 5 else n
    w10 = 10 if n >= 10 else n
    opp_d5 = sum(1 for x in opp[-w5:] if x == 'D')
    opp_d10 = sum(1 for x in opp[-w10:] if x == 'D')
    my_d5 = sum(1 for x in me[-w5:] if x == 'D')
    my_d10 = sum(1 for x in me[-w10:] if x == 'D')

    fail_count = 0
    start = max(0, n - 5)
    for i in range(start, n - 1):
        if me[i] == 'D' and opp[i] == 'D' and me[i + 1] == 'C' and opp[i + 1] == 'D':
            fail_count += 1

    if opp_d == n:
        return 'D'
    if opp_d5 >= 5 and (opp_rate >= 0.4 or fail_count >= 1 or my_d5 <= 3):
        return 'D'
    if opp_d10 >= 9 and (opp_rate >= 0.35 or fail_count >= 2):
        return 'D'

    after_c = 0
    after_c_d = 0
    after_d = 0
    after_d_d = 0
    for i in range(n - 1):
        if me[i] == 'C':
            after_c += 1
            if opp[i + 1] == 'D':
                after_c_d += 1
        else:
            after_d += 1
            if opp[i + 1] == 'D':
                after_d_d += 1

    p_after_c = after_c_d / after_c if after_c > 0 else 0.0
    p_after_d = after_d_d / after_d if after_d > 0 else -1.0

    unprov = 0
    i = n - 1
    while i >= 0 and me[i] == 'C' and opp[i] == 'D':
        unprov += 1
        i -= 1

    dd = 0
    i = n - 1
    while i >= 0 and me[i] == 'D' and opp[i] == 'D':
        dd += 1
        i -= 1

    if opp_d == 0:
        if n >= 2 and me[-1] == 'C' and opp[-1] == 'C' and me[-2] == 'D' and opp[-2] == 'C':
            return 'D'
        if last_me == 'D' and last_opp == 'C':
            if n >= 3 and me[-2] == 'C' and opp[-2] == 'C' and me[-3] == 'D' and opp[-3] == 'C':
                return 'D'
            return 'C' if n < 80 else 'D'
        if n >= 20 and last_opp == 'C':
            return 'D'
        return 'C'

    if opp_d5 <= 1 and opp_rate <= 0.25:
        if last_opp == 'C' and p_after_d >= 0 and p_after_d <= 0.3 and after_d >= 1:
            if n >= 35:
                return 'D'
        if n >= 90 and last_opp == 'C':
            if p_after_d < 0:
                if opp_d <= 3:
                    return 'D'
            elif p_after_d <= 0.6:
                return 'D'

    if last_me == 'C' and last_opp == 'D' and me[-2] == 'D' and opp[-2] == 'D':
        return 'D'

    if last_opp == 'D':
        if dd >= 2:
            if opp_rate < 0.65 and fail_count == 0:
                return 'C'
            return 'D'
        if dd == 1:
            if opp_d >= 3 or opp_d5 >= 3 or opp_rate > 0.35:
                return 'D'
            return 'C'
        if unprov >= 2:
            return 'D'
        if unprov == 1:
            if opp_d >= 6 and opp_rate > 0.35:
                return 'D'
            if p_after_c > 0.45 and opp_d >= 3:
                return 'D'
            return 'C'
        return 'D' if opp_rate > 0.45 else 'C'

    if opp_rate > 0.5:
        return 'D'
    if opp_d10 >= 7 and opp_d5 >= 4:
        return 'D'
    if last_me == 'D' and last_opp == 'C' and p_after_d >= 0 and p_after_d <= 0.2 and opp_d <= 3:
        return 'D'

    return 'C'
